Object.assign(window.I18N,{"Wer hat dich am meisten angegriffen?": "Hver réðst mest á þig?", "niemand besonders": "enginn sérstakur", "konnte von einem Angriff auf {0} nicht ablassen, obwohl er dort deutlich mehr verlor als gewann": "gat ekki hætt árás á {0} þótt hann tapaði þar mun meira en hann vann", "Sunk-Cost-Effekt": "sokkinn kostnaður", "Verlustaversion": "tapsfælni", "Vergeltungsimpuls": "hefndarhvöt", "Impulsives Schnelldenken": "hvatvís hraðhugsun", "Feindseligkeitsverzerrung": "fjandsamleg eignunarskekkja", "Introspektionsillusion": "sjálfsskoðunarblekking", "Selbstwertdienliche Verzerrung": "sjálfhverf skekkja", "Kognitive Verzerrung – Erklärung öffnen": "Hugræn skekkja – opna skýringu", "Psychologie": "Sálfræði"});
